-- Queer Atlas: Saugatuck, Salt Lake City, Halifax, Minneapolis and Cardiff.
-- Researched 2026-08-27 from first-party operators, Pride/community organisations,
-- destination-marketing bodies and public-health providers. Idempotent.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
declare k text;
begin
  foreach k in array array['country:united-states','country:canada','country:united-kingdom'] loop
    if not exists(select 1 from public.qa_qari_profiles where destination_key=k and scope_type='country' and is_published=true) then
      raise exception 'Published QARI profile % is required before this city batch can run.', k;
    end if;
  end loop;
end;
$qa_require_qari$;

with src as (
 select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"saugatuck","name":"Saugatuck","title":"Queer Saugatuck","country":"United States","country_code":"US","latitude":42.6550,"longitude":-86.2016,"timezone":"America/Detroit","vibe":"lakeside, multigenerational and resort-social","local_mood":"Saugatuck and neighbouring Douglas form one shared queer destination: beach days, arts businesses, LGBTQ-owned lodging and the large Dunes entertainment resort are connected by a small-town summer rhythm.","queer_status":"Dedicated resorts and year-round queer-owned businesses give the area unusual visibility for its size, while access and opening patterns remain strongly seasonal.","crowd_profile":"Midwest weekenders, gay men, lesbian couples, trans and non-binary visitors, artists, campers, older regulars and mixed families overlap without forming one single nightlife crowd.","introduction":"Read Saugatuck together with Douglas and nearby Fennville. The Dunes is both accommodation and the main nightlife complex, Campit provides an LGBTQ outdoor-resort community, Uncommon Coffee supplies a queer-founded daytime room, and Oval Beach is the classic queer-popular public beach. CommUNITY Pride and a dense network of LGBTQ-owned lodging make the destination deeper than its tiny population suggests.","guide_items":[{"title":"About","text":"The Art Coast is a two-town queer resort ecosystem rather than a conventional gay district. Dedicated resorts, galleries, hospitality businesses and Pride organising share the load."},{"title":"Districts","text":"Downtown Saugatuck holds cafés, shopping and the riverfront; Douglas contains The Dunes and several stays; Campit sits south near Fennville and requires a car."},{"title":"Safety","text":"The resort area is openly welcoming, but beach, boating and alcohol safety matter. Confirm seasonal transport and never treat a public beach as a private cruising venue."},{"title":"Nightlife","text":"The Dunes programme drives late nights; Campit is registered-guest community space. Check current calendars because weekdays and shoulder season differ sharply from summer weekends."},{"title":"Cost","text":"Summer weekends and festivals raise room rates. Parking, beach admission and ride availability should be planned before relying on a compact-looking map."}],"guide_sources":[{"label":"Saugatuck tourism LGBTQ guide","url":"https://saugatuck.com/why-the-art-coast-is-a-must-visit-destination-for-the-lgbtq-traveler/"},{"label":"The Dunes Resort","url":"https://dunesresort.com/"},{"label":"Community Pride MI","url":"https://www.communitypridemi.org/"}],"safety_context":"Saugatuck-Douglas has unusually visible queer infrastructure, but it is seasonal and geographically spread. Confirm venue dates, arrange a sober ride between towns and respect campground membership and public-beach rules.","qari_key":"country:united-states"},
 {"slug":"salt_lake_city","name":"Salt Lake City","title":"Queer Salt Lake City","country":"United States","country_code":"US","latitude":40.7608,"longitude":-111.8910,"timezone":"America/Denver","vibe":"mountain-framed, resilient and unexpectedly visible","local_mood":"Salt Lake City's queer life balances long-running bars, newer drag-led clubs, community infrastructure and a visible Harvey Milk Boulevard within Utah's more conservative statewide context.","queer_status":"A concentrated group of dedicated venues and multiple Pride organisations creates real urban visibility; state politics and liquor rules still shape the visitor experience.","crowd_profile":"Local gay men, lesbians, trans and non-binary people, former-LDS residents, students, drag audiences, leather communities, allies and outdoor travellers mix across distinct venues.","introduction":"Salt Lake City has a real permanent circuit rather than occasional queer nights alone. Try-Angles and Sun Trapp provide veteran bar culture, MILK+ and Why Kiki lead drag and dance programming, and Metro Music Hall hosts larger queer productions. Utah Pride Center adds year-round resources, while SLC Pride and Utah Pride programmes reflect a community with more than one organising voice.","guide_items":[{"title":"About","text":"The city is more progressive and queer-visible than Utah stereotypes imply, but local warmth should not be confused with uniform statewide politics."},{"title":"Districts","text":"Harvey Milk Boulevard around 900 South links Try-Angles and MILK+; Sun Trapp and Metro sit west of downtown, while Why Kiki is central."},{"title":"Safety","text":"Bring physical ID because Utah bars check everyone. Track late-night transport, altitude and dehydration, and consult current local guidance for policy changes."},{"title":"Nightlife","text":"Start with a neighbourhood bar, then move to MILK+, Why Kiki or a Metro programme. Theme nights materially change audience, dress and cover."},{"title":"Cost","text":"Covers and special events vary; downtown hotels can spike around conventions and ski weekends, although TRAX makes much of the circuit reachable."}],"guide_sources":[{"label":"Visit Salt Lake LGBTQ guide","url":"https://www.visitsaltlake.com/articles/post/out-in-salt-lake-city-an-lgbtq-guide-to-utahs-unexpectedly-cool-capital/"},{"label":"Visit Salt Lake bars","url":"https://www.visitsaltlake.com/blog/stories/post/salt-lakes-lgbtq-bars/"},{"label":"Utah Pride Center","url":"https://utahpridecenter.org/"}],"safety_context":"Salt Lake has durable queer venues and support organisations alongside a changeable political environment. Carry ID, verify event rules and distinguish city-level inclusion from statewide conditions.","qari_key":"country:united-states"},
 {"slug":"halifax","name":"Halifax","title":"Queer Halifax","country":"Canada","country_code":"CA","latitude":44.6488,"longitude":-63.5752,"timezone":"America/Halifax","vibe":"maritime, community-led and newly resurgent","local_mood":"Halifax's queer scene combines established community businesses with a new generation of bars after several venue closures; calendars and grassroots networks matter as much as a fixed district.","queer_status":"Stardust, Rumours and BACKLOT restore permanent nightlife capacity, while prideHealth, The Youth Project and queer-run daytime businesses provide deeper regional infrastructure.","crowd_profile":"Two-spirit and LGBTQIA+ locals, university students, military and maritime communities, drag audiences, queer youth, older organisers and Atlantic Canadian visitors meet across different spaces.","introduction":"Halifax is in a period of queer-venue renewal. Stardust offers food, cocktails and performance, Rumours runs a larger queer-owned dance and show programme, and BACKLOT adds an intimate Gottingen Street room. Glitter Bean and Venus Envy remain important daytime anchors. Indulge is deliberately excluded because it closed; current operator evidence is favoured over inherited directory lists.","guide_items":[{"title":"About","text":"Atlantic Canada's largest city supports both nightlife and regional service infrastructure, but venue turnover makes current first-party checks essential."},{"title":"Districts","text":"Barrington and Lower Water hold Stardust, Rumours and Venus Envy; Gottingen has BACKLOT; Glitter Bean sits by the universities on Spring Garden Road."},{"title":"Safety","text":"Downtown is walkable, with ordinary waterfront weather, late-night and consent awareness. Respect Indigenous two-spirit terminology and community-specific programmes."},{"title":"Nightlife","text":"Each current room has a different scale: dinner and shows at Stardust, larger club energy at Rumours, and intimate event-led nights at BACKLOT."},{"title":"Cost","text":"Festival and summer dates lift hotel prices. Some Pride events are ticketed, and late-night rides should be budgeted when weather turns."}],"guide_sources":[{"label":"Discover Halifax 2SLGBTQIA+ resources","url":"https://discoverhalifaxns.com/plan/lgbthalifaxresources/"},{"label":"Halifax Pride","url":"https://www.halifaxpride.com/"},{"label":"prideHealth","url":"https://www.nshealth.ca/pridehealth"}],"safety_context":"Halifax has strong community organisations but a recently changing venue map. Verify doors and calendars on the day, use weather-aware transport and treat youth and clinical services as protected support spaces.","qari_key":"country:canada"},
 {"slug":"minneapolis","name":"Minneapolis","title":"Queer Minneapolis","country":"United States","country_code":"US","latitude":44.9778,"longitude":-93.2650,"timezone":"America/Chicago","vibe":"historic, expansive and community-inventive","local_mood":"Minneapolis sustains one of the Midwest's broadest queer venue mixes, from veteran downtown institutions and neighbourhood bars to women's sports, theatre, leather and youth infrastructure.","queer_status":"Multiple permanent venues, a major free Pride festival and specialised library, clinic and youth services create substantial local infrastructure despite wider state and national policy volatility.","crowd_profile":"Gay men, lesbians, trans and non-binary people, sports fans, leather communities, drag and theatre audiences, queer youth, BIPOC communities and allies find different entry points.","introduction":"Minneapolis should not be reduced to one Hennepin Avenue bar crawl. The Saloon and Gay 90s carry downtown scale; 19 Bar preserves neighbourhood history; LUSH and Roxy's connect food with performance; EAGLE MPLS serves bar, brunch and leather-adjacent communities; Jetset adds a smaller dance room; and A Bar of Their Own centres women's sports. Quatrefoil, Family Tree and QUEERSPACE make the guide useful beyond nightlife.","guide_items":[{"title":"About","text":"The scene is large enough to specialise by audience and format. That diversity is more informative than labelling every stop simply gay-friendly."},{"title":"Districts","text":"Downtown and Loring Park hold the densest cluster; Northeast contains LUSH and Jetset; Seward has A Bar of Their Own; services extend south."},{"title":"Safety","text":"Winter weather and long distances matter. Use normal late-night transport care, verify 18+/21+ rules and respect youth and clinical privacy."},{"title":"Nightlife","text":"Programme first: drag, leather, karaoke, theatre, sports and DJs draw different crowds. Check official calendars rather than assuming every night is interchangeable."},{"title":"Cost","text":"Twin Cities Pride is free, while covers, shows and rides vary. Central hotels peak during Pride, sports and convention weekends."}],"guide_sources":[{"label":"Meet Minneapolis LGBTQ bars","url":"https://www.minneapolis.org/lgbtq-community/bars-clubs/"},{"label":"Twin Cities Pride","url":"https://tcpride.org/"},{"label":"Meet Minneapolis LGBTQ businesses","url":"https://www.minneapolis.org/lgbtq-community/businesses/"}],"safety_context":"Minneapolis offers extensive queer infrastructure but a geographically spread scene and severe seasonal weather. Confirm access ages, use reliable late transport and check current state and national guidance.","qari_key":"country:united-states"},
 {"slug":"cardiff","name":"Cardiff","title":"Queer Cardiff","country":"United Kingdom","country_code":"GB","latitude":51.4816,"longitude":-3.1791,"timezone":"Europe/London","vibe":"compact, cabaret-forward and proudly Welsh","local_mood":"Cardiff's central queer circuit is unusually walkable, linking historic pubs, drag bars, late clubs and a world-class LGBTQ film festival within a few streets.","queer_status":"A durable cluster around St Mary Street and Churchill Way, Pride Cymru, Iris Prize and youth services gives Wales' capital strong public visibility.","crowd_profile":"Welsh LGBTQ+ locals, students, drag audiences, gay men, lesbians, trans and non-binary people, film communities, rugby visitors and allies overlap across clearly different rooms.","introduction":"Cardiff combines heritage and reinvention. The Golden Cross remains the historic pub and cabaret anchor; Mary's leads St Mary Street singalong energy; Pulse and The Kings sustain the Churchill Way club circuit; Eclipse now occupies the former Eagle basement under a new identity; and Dock Feeder offers a broader welcoming bar. The Queer Emporium is not inserted as permanent because its announced August 2026 closure makes the record unstable. Iris Prize provides the strongest confirmed future event.","guide_items":[{"title":"About","text":"The capital's queer core is compact and publicly visible, with Welsh-language identity and major annual events adding depth beyond nightlife."},{"title":"Districts","text":"St Mary Street and Churchill Way form the main walkable circuit; Charles Street holds Eclipse. Film and Pride venues spread only slightly farther."},{"title":"Safety","text":"The centre is busy on event and rugby nights. Use ordinary late-night awareness, confirm basement accessibility and follow each venue's consent rules."},{"title":"Nightlife","text":"Golden Cross is the historic opener; Mary's is cabaret-led; Pulse, Kings and Eclipse run later. Programming determines the best audience fit."},{"title":"Cost","text":"Many bars have free early access but clubs and shows vary. Rugby, Pride and graduation weekends can sharply raise room prices."}],"guide_sources":[{"label":"Visit Cardiff LGBTQ guide","url":"https://www.visitcardiff.com/2025/09/cardiff-friendly-city-lgbtq/"},{"label":"Visit Wales LGBTQ places","url":"https://www.visitwales.com/inspire-me/city-breaks/guide-some-best-lgbt-places-cardiff"},{"label":"Iris Prize","url":"https://irisprize.org/"}],"safety_context":"Cardiff's queer venues are central and established, but operator changes can outpace old directories. Verify current names and hours, plan around major-event crowds and check step-free access for basement rooms.","qari_key":"country:united-kingdom"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c cross join lateral(select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with raw_places as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"Campit Outdoor Resort","city":"saugatuck","type":"other","description":"A seasonal LGBTQ outdoor resort and campground near Fennville with cabins, RV and tent sites, pool, clubhouse and programmed community weekends. Registration and guest rules make it a destination community rather than a casual public bar.","hours":"Seasonal; registered-guest access and event times vary by current calendar.","link":"https://www.campitresort.com/","location":"6635 118th Avenue, Fennville, MI 49408, USA","lat":42.549650,"lng":-86.191750,"vibe":"social LGBTQ campground balancing pool days, themed weekends and wooded downtime","q":"Holiday weekends create check-in and pool peaks; complete registration before driving to the gate.","best":"Choose a themed weekend matching the desired crowd, or quieter weekdays for a slower campground stay.","crowd":"LGBTQ adults, couples, solo campers, RV travellers and friend groups; event audiences vary by programme.","dress":"Camp casual and swimwear fit common areas; themed parties publish separate expectations.","staff":"The operator explicitly positions Campit as an LGBTQ resort and publishes conduct and guest procedures.","sources":["https://www.campitresort.com/","https://saugatuck.com/business/campit-outdoor-resort/"]},
 {"name":"Uncommon Coffee Roasters","city":"saugatuck","type":"cafe","description":"A queer-founded, minority-owned downtown coffeehouse and roastery that describes itself as a safe space and employs queer people and allies. It is the strongest verified daytime queer anchor in central Saugatuck.","hours":"Sunday-Thursday 07:00-18:00; Friday-Saturday 07:00-19:00.","link":"https://www.uncommoncoffeeroasters.com/pages/uncommon-coffee-roasters","location":"127 Hoffman Street, Saugatuck, MI 49453, USA","lat":42.656365,"lng":-86.204755,"vibe":"welcoming queer-founded coffee room with local regulars and summer visitor energy","q":"Morning and summer-weekend lines can form; counter service normally moves faster outside breakfast peaks.","best":"Weekday mornings suit local atmosphere; afternoons work for a calm queer-friendly break between shops.","crowd":"Queer locals and staff, artists, remote workers, families and resort visitors share the room.","dress":"Come-as-you-are café clothing; beach and cycling attire are routine.","staff":"The business explicitly documents queer founding, minority ownership and a safe-space employment culture.","sources":["https://www.uncommoncoffeeroasters.com/pages/uncommon-coffee-roasters"]},
 {"name":"Oval Beach","city":"saugatuck","type":"other","description":"Saugatuck's public Lake Michigan beach, long identified by official destination guides as especially popular with LGBTQ visitors. It is not a private queer venue: city rules, lifeguard status and public-family expectations apply.","hours":"Seasonal gate generally 08:00-22:00; verify current city access, parking and lifeguard information.","link":"https://www.saugatuckcity.com/oval-beach.html","location":"690 Perryman Street, Saugatuck, MI 49453, USA","lat":42.662400,"lng":-86.216030,"vibe":"wide Lake Michigan beach with a visible queer following and mixed public crowd","q":"Sunny summer weekends fill parking and the chain ferry approach; arrive early or use authorised transport.","best":"Late morning through sunset in warm weather, with wind and water conditions checked first.","crowd":"LGBTQ visitors, couples, families, swimmers and general beachgoers; no section is private.","dress":"Ordinary public-beach swimwear; comply with bans on alcohol, smoking and dogs.","staff":"City management is general-public; queer relevance comes from sustained destination-guide evidence, not special beach governance.","sources":["https://www.saugatuckcity.com/oval-beach.html","https://saugatuck.com/why-the-art-coast-is-a-must-visit-destination-for-the-lgbtq-traveler/"]},

 {"name":"Club Try-Angles","city":"salt_lake_city","type":"bar","description":"A long-running 21+ gay neighbourhood bar with patio, pool, darts, karaoke, low-cost pours and changing leather, underwear and community theme nights.","hours":"Monday-Friday from 16:00; Saturday from 18:00; Sunday from 14:00; verify closing and event times.","link":"https://clubtryangles.com/","location":"251 West 900 South, Salt Lake City, UT 84101, USA","lat":40.749552,"lng":-111.898562,"vibe":"unpretentious gay dive-bar warmth that becomes louder on theme nights","q":"ID is checked for every entrant; Pride and theme nights can create a compact door line.","best":"Early evening for conversation, Thursday karaoke or published theme nights for a fuller crowd.","crowd":"Gay men anchor the room alongside broader LGBTQ regulars, leather guests and allies.","dress":"Casual bar wear ordinarily; underwear and leather events publish opt-in themes, never assumptions.","staff":"A dedicated gay bar with long local history and current official/community-tourism confirmation.","sources":["https://clubtryangles.com/","https://www.visitsaltlake.com/articles/post/out-in-salt-lake-city-an-lgbtq-guide-to-utahs-unexpectedly-cool-capital/"]},
 {"name":"The Sun Trapp","city":"salt_lake_city","type":"bar","description":"Salt Lake City's oldest operating LGBTQ+ bar, known for a large patio, mason-jar drinks, dancing and a broad community crowd west of downtown.","hours":"Tuesday-Sunday 11:00-01:00; closed Monday; confirm holiday changes.","link":"https://www.suntrappslc.com/","location":"102 South 600 West, Salt Lake City, UT 84101, USA","lat":40.766941,"lng":-111.908572,"vibe":"veteran LGBTQ patio bar shifting from daytime socialising to late dancing","q":"Universal ID checks apply; weekend dance hours and Pride dates produce the longest wait.","best":"Patio afternoons for conversation, then Friday or Saturday late evening for dancing.","crowd":"A multigenerational LGBTQ crowd, downtown visitors and allies; the patio broadens the mix.","dress":"Relaxed bar clothing; weather layers matter on the patio.","staff":"The venue explicitly identifies as LGBTQ and is independently confirmed by Visit Salt Lake.","sources":["https://www.suntrappslc.com/","https://www.visitsaltlake.com/plan-your-visit/trip-ideas-itineraries/lgbtq-friendly/"]},
 {"name":"MILK+","city":"salt_lake_city","type":"club","description":"An LGBTQ nightclub and food-led social venue on Harvey Milk Boulevard with drag, karaoke, game nights, DJs, patio service and a deliberately broad queer audience.","hours":"Thursday-Sunday 18:00-02:00; individual programmes may start earlier.","link":"https://milkslc.com/","location":"49 East 900 South, Salt Lake City, UT 84111, USA","lat":40.750021,"lng":-111.889481,"vibe":"polished queer club energy combining dinner, drag, games and late dancing","q":"Ticketed drag and weekend club nights can queue; valid physical ID is essential.","best":"Arrive for the named show if performance matters, or later for the dance-floor peak.","crowd":"Queer adults across genders, drag audiences, younger clubgoers and allies.","dress":"Expressive nightlife looks are welcome; specific parties may announce themes.","staff":"The operator explicitly describes MILK+ as an LGBTQ venue built for community and entertainment.","sources":["https://milkslc.com/","https://www.visitsaltlake.com/articles/post/out-in-salt-lake-city-an-lgbtq-guide-to-utahs-unexpectedly-cool-capital/"]},
 {"name":"Why Kiki","city":"salt_lake_city","type":"bar","description":"A queer-owned and staffed inclusive cocktail, drag and dance bar with frequent shows, Sunday brunch and a downstairs silent disco.","hours":"Programme-led, generally Thursday-Sunday; consult the official calendar for doors and closing.","link":"https://www.whykikibar.com/","location":"69 West 100 South, Salt Lake City, UT 84101, USA","lat":40.767003,"lng":-111.893457,"vibe":"playful drag-forward downtown bar moving from cocktails to full dance energy","q":"Brunch and headline drag reservations fill; club entry later uses Utah ID checks.","best":"Book the exact drag or brunch programme, or arrive before the late-night dance surge.","crowd":"Queer locals, drag fans, birthday groups, younger dancers and supportive allies.","dress":"Colourful self-expression works; ordinary smart-casual is equally accepted.","staff":"The venue states it is run and staffed by LGBTQ people while welcoming everyone.","sources":["https://www.whykikibar.com/","https://www.visitsaltlake.com/articles/post/out-in-salt-lake-city-an-lgbtq-guide-to-utahs-unexpectedly-cool-capital/"]},
 {"name":"Metro Music Hall","city":"salt_lake_city","type":"club","description":"A live-music and event hall repeatedly hosting major drag, queer touring shows and local LGBTQ productions. It is an ally venue with queer programming, not a dedicated gay bar every night.","hours":"Event-led; doors and age rules are published per show.","link":"https://metromusichall.com/","location":"615 West 100 South, Salt Lake City, UT 84104, USA","lat":40.766930,"lng":-111.909011,"vibe":"larger-format concert room where queer touring acts and drag nights take over the calendar","q":"Ticketed shows create a security and ID line; sold-out events require earlier arrival.","best":"Attend only for a verified queer programme and follow its published door time.","crowd":"Concert audiences vary; queer events draw drag fans, LGBTQ locals and allies.","dress":"Show-specific self-expression; practical standing-room footwear helps.","staff":"Visit Salt Lake identifies Metro as an ally venue with frequent drag and queer events; not queer-exclusive.","sources":["https://metromusichall.com/","https://www.visitsaltlake.com/blog/stories/post/salt-lakes-lgbtq-bars/"]},
 {"name":"Under the Umbrella Bookstore","city":"salt_lake_city","type":"gay_store","description":"A queer little bookstore carrying LGBTQ+ books, gifts and community programming in the city's Granary District. Its curated shelves provide a sober, all-ages daytime complement to the bar circuit.","hours":"Schedule varies; verify current shop and event hours on the official site before travel.","link":"https://www.undertheumbrellabookstore.com/","location":"511 West 200 South, Suite 120, Salt Lake City, UT 84101, USA","lat":40.764659,"lng":-111.905941,"vibe":"community-minded queer bookstore centring representation, conversation and sober connection","q":"Ordinary shopping has no queue; launches and author events can require early arrival or registration.","best":"Browse during daytime hours or choose a named event that matches the desired age and topic.","crowd":"Queer readers across ages, authors, families, students and supportive allies.","dress":"Everyday retail clothing; respect the privacy of community-event participants.","staff":"The shop explicitly identifies as queer and curates LGBTQ+ authors and content as its core mission.","sources":["https://www.undertheumbrellabookstore.com/","https://www.undertheumbrellabookstore.com/uploads/b/bf6a03c0-ad29-11eb-af2f-916932a4f5c3/Under%20the%20Umbrella_Publicity%20Kit_2025.pdf"]},

 {"name":"Stardust Bar + Kitchen","city":"halifax","type":"bar","description":"A downtown queer bar and kitchen combining cocktails, dinner, drag, cabaret and community events in an intimate Barrington Street room.","hours":"Wednesday-Thursday 15:00-00:00; Friday 15:00-02:00; Saturday 11:00-02:00; Sunday 11:00-00:00.","link":"https://www.stardustbar.ca/","location":"1688 Barrington Street, Halifax, NS B3J 2A2, Canada","lat":44.647117,"lng":-63.574167,"vibe":"warm queer supper-club atmosphere with polished drinks and close-up performance","q":"Brunches, drag and cabaret seatings benefit from reservations; late bar entry varies by capacity.","best":"Book the named performance or visit early for food before the room becomes show-led.","crowd":"Queer adults across genders, drag and theatre audiences, couples and allies.","dress":"Come-as-you-are through expressive cabaret looks; seated dining remains casual.","staff":"The operator explicitly presents Stardust as a queer bar and community gathering space.","sources":["https://www.stardustbar.ca/"]},
 {"name":"Rumours HFX","city":"halifax","type":"club","description":"A queer-owned Lower Water Street bar and nightclub with drag, DJs, karaoke, themed parties, food and a larger dance-floor format.","hours":"Open seven days with programme-specific hours; check the official calendar before travel.","link":"https://www.rumourshfx.com/","location":"1668 Lower Water Street, Halifax, NS B3J 1S4, Canada","lat":44.647209,"lng":-63.571387,"vibe":"high-energy queer-owned club mixing drag spectacle, dancing and community nights","q":"Headline shows and weekend dancing create the main queue; tickets do not remove ID checks.","best":"Match arrival to the show or theme; earlier evening suits food, later hours suit dancing.","crowd":"A broad 2SLGBTQIA+ crowd, students, drag fans, visitors and allies.","dress":"Expressive party wear is common; themed events publish optional prompts.","staff":"Rumours explicitly identifies as queer-owned and builds its programme around queer community.","sources":["https://www.rumourshfx.com/"]},
 {"name":"BACKLOT HFX","city":"halifax","type":"bar","description":"A small queer Gottingen Street bar opened in 2026 with drag, DJs, karaoke and community-led events. Its newness means the live social calendar is more reliable than inherited opening-hour directories.","hours":"Event-led; verify current doors and age rules on the operator's social channel.","link":"https://www.instagram.com/backlothfx/","location":"2103 Gottingen Street, Halifax, NS B3K 3B2, Canada","lat":44.651905,"lng":-63.583008,"vibe":"intimate new queer bar with grassroots performance and neighbourhood energy","q":"The small room reaches capacity quickly for launches and drag; arrive near published doors.","best":"Choose a named event rather than assuming identical nightly operation.","crowd":"Queer locals, performers, students, North End regulars and friends.","dress":"Casual and expressive; programme themes may shift the room.","staff":"Local queer press documents BACKLOT as a dedicated queer venue opened in March 2026.","sources":["https://wayves.ca/backlot-hfx-2026-03","https://www.instagram.com/backlothfx/"]},
 {"name":"Glitter Bean Café","city":"halifax","type":"cafe","description":"A queer-centric, unionised worker-owned cooperative café near the universities, functioning as an affirming daytime room as well as a coffee shop.","hours":"Monday-Friday 07:30-18:00; Saturday 10:00-17:00; Sunday 11:00-16:00.","link":"https://www.glitterbeancafe.com/contact","location":"5896 Spring Garden Road, Halifax, NS B3H 0A6, Canada","lat":44.640758,"lng":-63.584784,"vibe":"queer-centric cooperative café with student, activist and neighbourhood warmth","q":"Lunch and campus peaks can fill seats; counter ordering remains straightforward.","best":"Weekday mid-morning or afternoon for the strongest community-café feel.","crowd":"Queer and trans locals, students, workers, activists and general café customers.","dress":"Everyday café clothing; no appearance gate.","staff":"Discover Halifax identifies it as 2SLGBTQIA+ run, and the cooperative documents worker ownership.","sources":["https://www.glitterbeancafe.com/contact","https://discoverhalifaxns.com/plan/lgbthalifaxresources/lgbt-allied-businesses/"]},
 {"name":"Venus Envy Halifax","city":"halifax","type":"gay_store","description":"A queer- and trans-owned bookstore and sex shop providing inclusive products, books, education and a sensory-friendly Sunday shopping window.","hours":"Monday-Thursday 11:00-19:00; Friday-Saturday 11:00-20:00; Sunday 11:00-18:00; sensory-friendly Sunday 16:00-18:00.","link":"https://venusenvy.ca/pages/halifax-store","location":"1727 Barrington Street, Halifax, NS B3J 2A4, Canada","lat":44.647758,"lng":-63.574190,"vibe":"sex-positive queer bookstore and shop combining practical access with community education","q":"Ordinary retail entry; workshops or launches may have separate registration and capacity.","best":"Use the quieter Sunday sensory window if reduced music, scent and conversation helps.","crowd":"Queer and trans shoppers, readers, educators, couples and curious adults.","dress":"Ordinary retail attire; privacy and consent around other shoppers matter.","staff":"The business explicitly identifies as queer- and trans-owned and publishes affirming access information.","sources":["https://venusenvy.ca/pages/halifax-store"]},

