$qa_events$) e(name text,city text,description text,link text,date text,start_date timestamptz,end_date timestamptz,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,host text,sources jsonb)
), events as (
 select e.*,jsonb_build_object('entry_wait',q,'best_arrival',best,'crowd_mix',crowd,'dress_code',dress,'host_inclusivity',host,'source_urls',sources,'research_status','official_organiser_dates','updated_at','2026-08-27T00:00:00Z') intel from raw_events e
), upd as (
 update public.events t set description=e.description,link=e.link,date=e.date,start_date=e.start_date,end_date=e.end_date,location=e.location,lat=e.lat,lng=e.lng,vibe=e.vibe,vibe_tags=array[]::text[],event_intel=e.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from events e where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)) returning t.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from events e where not exists(select 1 from public.events t where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)));

