$qa_services$) s(name text,city text,type text,provider text,contact text,booking text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,lead text,best text,crowd text,prep text,incl text,sources jsonb)
), services as (
 select s.*,jsonb_build_object('booking_lead_time',lead,'best_time',best,'client_mix',crowd,'preparation',prep,'provider_inclusivity',incl,'source_urls',sources,'research_status','current_first_party_service_source','updated_at','2026-08-27T00:00:00Z') intel from raw_services s
), upd as (
 update public.services t set type=s.type,provider_name=s.provider,contact=s.contact,booking_link=s.booking,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source='Official provider pages; checked 2026-08-27',"lastChecked"=date '2026-08-27',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from services s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider,contact,booking,description,hours,link,location,lat,lng,vibe,array[]::text[],'Official provider pages; checked 2026-08-27',date '2026-08-27',true,intel,true,'approved',timezone('utc',now()) from services s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status(slug)
from (values('saugatuck'),('salt_lake_city'),('halifax'),('minneapolis'),('cardiff')) v(slug)
where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select c.slug,c.name,c.verified_place_count,c.seo_indexable,c.seo_requirements
from public.qa_cities c
where c.slug in('saugatuck','salt_lake_city','halifax','minneapolis','cardiff')
order by c.slug;

select lower(trim(city)) city,type,count(*) records
from (
 select city,'place'::text type from public.places
 union all select city,'event' from public.events
 union all select city,'service' from public.services
) x
where lower(trim(city)) in('saugatuck','salt_lake_city','halifax','minneapolis','cardiff')
group by lower(trim(city)),type order by city,type;
